-- KHET2KART SQL database schema and seed data

BEGIN TRANSACTION;
CREATE TABLE demand_requests (id TEXT PRIMARY KEY,product_name TEXT NOT NULL,buyer_name TEXT NOT NULL,required_quantity REAL NOT NULL,unit TEXT NOT NULL,preferred_price_low REAL,preferred_price_high REAL,location TEXT,required_by TEXT,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE farmer_profiles (user_id INTEGER PRIMARY KEY,farm_name TEXT,location TEXT,crops TEXT,rating REAL DEFAULT 0,verified INTEGER DEFAULT 0,distance_km REAL DEFAULT 0);
CREATE TABLE fpo_profiles (user_id INTEGER PRIMARY KEY,fpo_name TEXT,representative TEXT,location TEXT,member_count INTEGER DEFAULT 0);
CREATE TABLE logistics_routes (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,pickup_locations TEXT,destination TEXT,transport_partner TEXT,estimated_distance_km REAL,estimated_delivery_minutes REAL,route_efficiency REAL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT NOT NULL,product_id INTEGER NOT NULL,farmer_id INTEGER NOT NULL,quantity REAL NOT NULL,price REAL NOT NULL);
CREATE TABLE orders (id TEXT PRIMARY KEY,group_id TEXT NOT NULL,consumer_id INTEGER NOT NULL,buyer_name TEXT NOT NULL,status TEXT NOT NULL,delivery_fee REAL NOT NULL DEFAULT 0,platform_fee REAL NOT NULL DEFAULT 0,total_amount REAL NOT NULL,placed_at TEXT NOT NULL, payment_method TEXT NOT NULL DEFAULT 'upi');
CREATE TABLE pooled_lots (id TEXT PRIMARY KEY,fpo_id INTEGER NOT NULL,product_name TEXT NOT NULL,quality_grade TEXT,sale_price REAL,status TEXT NOT NULL,contributions TEXT NOT NULL,verification TEXT,logistics TEXT,created_at TEXT NOT NULL);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT NOT NULL,price REAL NOT NULL CHECK(price >= 0),unit TEXT NOT NULL,available_quantity REAL NOT NULL CHECK(available_quantity >= 0),quality_grade TEXT,image TEXT,harvest_date TEXT,availability_date TEXT,description TEXT,farmer_id INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reviews (id INTEGER PRIMARY KEY AUTOINCREMENT,farmer_id INTEGER NOT NULL,product_id INTEGER,consumer_id INTEGER,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, order_id TEXT);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE,aadhaar TEXT UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('farmer','consumer','fpo')),linked_id INTEGER,is_premium INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, consumer_location TEXT);
DELETE FROM "sqlite_sequence";

-- Basic FPO operational demo data
COMMIT;
